// Auto-generated by the per-command split.
const os = require('os');
const dns = require('dns').promises;
const tls = require('tls');
const crypto = require('crypto');
const moment = require('moment-timezone');
const fetch = require('node-fetch');
const ytSearch = require('yt-search');
const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

const ANIME_REACTIONS = [
  'bully', 'cuddle', 'cry', 'hug', 'awoo', 'kiss', 'lick', 'pat', 'smug', 'bonk',
  'yeet', 'blush', 'smile', 'wave', 'highfive', 'handhold', 'nom', 'bite', 'glomp',
  'slap', 'kill', 'kickreact', 'happy', 'wink', 'poke', 'dance', 'cringe'
];

// "kickreact" is this command's name (so it doesn't collide with the real
// group .kick command), but the actual waifu.pics API endpoint is "kick".
const ENDPOINT_OVERRIDES = { kickreact: 'kick' };

function buildCommand() {
  const __args = [ANIME_REACTIONS, 'Anime Reactions', 'Anime reaction gif commands', async ({ sock, from, msg, body, settings, cfg }) => {
  const cmd = body.slice((settings.prefix || cfg.prefix).length).trim().split(/\s+/)[0].toLowerCase();
  const endpoint = ENDPOINT_OVERRIDES[cmd] || cmd;
  try {
    const res = await fetch(`https://api.waifu.pics/sfw/${endpoint}`);
    const data = await res.json();
    await sock.sendMessage(from, { image: { url: data.url }, caption: cmd }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: `Couldn't fetch a ${cmd} gif right now.` }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
